from pathlib import Path
p=[]
for raw in Path('prog.pw9').read_text().splitlines():
 s=raw.split(';')[0].strip()
 if s:p.append(s.split())
r={x:0 for x in 'abcd'}; pc=0; n=0; out=[]
def val(s): return r[s] if s in r else int(s)
while 0<=pc<len(p):
 ins=p[pc]; op=ins[0]; n+=1; nxt=pc+1
 if op=='set': r[ins[1]]=val(ins[2])%65536
 elif op=='add': r[ins[1]]=(r[ins[1]]+val(ins[2]))%65536
 elif op=='mul': r[ins[1]]=(r[ins[1]]*val(ins[2]))%65536
 elif op=='mod':
  x=val(ins[2]);
  if x>0:r[ins[1]]%=x
 elif op=='dec': r[ins[1]]=max(0,r[ins[1]]-1)
 elif op=='jnz':
  if val(ins[1])"'!=0:nxt=pc+val(ins[2])
 elif op=='"'skp':
  if val(ins[1])<val(ins[2]):nxt=pc+2
 elif op=='out':out.append(val(ins[1]))
 pc=nxt
print('outputs',len(out),'sum',sum(out),'instructions',n)
print('final',r)
print('answer:',sum(out),n)
PY"

